code.java:
class Solution {
    public int findValueOfPartition(int[] nums){
        Arrays.sort(nums);
        int answer=Integer.MAX_VALUE;
        for(int i=1;i<nums.length;i++)answer=Math.min(answer,nums[i]-nums[i-1]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findValueOfPartition(nums:IntArray):Int{
        nums.sort();
        var answer=Int.MAX_VALUE;
        for(i in 1 until nums.size)answer=minOf(answer,nums[i]-nums[i-1]);
        return answer
    }
}

