class Solution {
    public:int findValueOfPartition(vector<int>& nums){
        sort(nums.begin(),nums.end());
        int answer=INT_MAX;
        for(int i=1;i<(int)nums.size();++i)answer=min(answer,nums[i]-nums[i-1]);
